import{_ as t,o as e,c as o,a2 as l}from"./chunks/framework.BZO4qERu.js";const p=JSON.parse('{"title":"DingTalk","description":"","frontmatter":{},"headers":[],"relativePath":"ja/integrations/channels/dingtalk.md","filePath":"ja/integrations/channels/dingtalk.md","lastUpdated":1792323081000}'),n={name:"ja/integrations/channels/dingtalk.md"};function r(i,a,d,s,h,g){return e(),o("div",null,[...a[0]||(a[0]=[l('<h1 id="dingtalk" tabindex="-1">DingTalk <a class="header-anchor" href="#dingtalk" aria-label="Permalink to &quot;DingTalk&quot;">​</a></h1><p>Memoh Bot を DingTalk につなぎ、組織内のプライベートチャットとグループチャットに対応させます。受信メッセージは DingTalk の Stream モード経由で届き、返信とメディアは DingTalk 公式 API 経由で送信されます。</p><div class="warning custom-block"><p class="custom-block-title">使用制限</p><ul><li>返信は完全なメッセージ単位で届き、token ごとのストリーミング出力は行われません。</li></ul></div><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>組織の DingTalk オープンプラットフォームにアクセスでき、アプリを作成する権限があること。</li><li>公開のコールバック URL は不要です。Memoh が DingTalk との Stream 長期接続を自動的に維持してメッセージを受信します。</li></ul><h2 id="手順" tabindex="-1">手順 <a class="header-anchor" href="#手順" aria-label="Permalink to &quot;手順&quot;">​</a></h2><h3 id="_1-dingtalk-オープンプラットフォームでアプリを作成する" tabindex="-1">1. DingTalk オープンプラットフォームでアプリを作成する <a class="header-anchor" href="#_1-dingtalk-オープンプラットフォームでアプリを作成する" aria-label="Permalink to &quot;1. DingTalk オープンプラットフォームでアプリを作成する&quot;">​</a></h3><p>組織の DingTalk オープンプラットフォームで次を行います。</p><ol><li>Bot として使うアプリを作成するか、既存のアプリを選びます。</li><li>そのアプリの Bot／メッセージ機能を有効にします。</li><li><strong>App Key</strong> と <strong>App Secret</strong> をコピーします。</li><li>アプリにメッセージ権限を付与し、利用者がアクセスできるように組織内で公開します。</li></ol><h3 id="_2-memoh-でチャネルを追加する" tabindex="-1">2. Memoh でチャネルを追加する <a class="header-anchor" href="#_2-memoh-でチャネルを追加する" aria-label="Permalink to &quot;2. Memoh でチャネルを追加する&quot;">​</a></h3><p>Memoh で次を行います。</p><ol><li>Bot の <strong>プラットフォーム</strong> タブを開きます。</li><li><strong>Add Channel</strong> をクリックし、<strong>DingTalk</strong> を選択します。</li><li><strong>App Key</strong> と <strong>App Secret</strong> を入力します。</li><li><strong>Save and Enable</strong> をクリックします。</li></ol><p>Memoh が DingTalk の Stream 長期接続を自動的に維持するため、webhook のコールバックアドレスを貼り付ける必要はありません。</p><h2 id="認証情報" tabindex="-1">認証情報 <a class="header-anchor" href="#認証情報" aria-label="Permalink to &quot;認証情報&quot;">​</a></h2><table tabindex="0"><thead><tr><th>フィールド</th><th>必須</th><th>説明</th></tr></thead><tbody><tr><td><strong>App Key</strong></td><td>はい</td><td>DingTalk アプリの Key。DingTalk オープンプラットフォームのアプリ認証情報からコピーします。</td></tr><tr><td><strong>App Secret</strong></td><td>はい</td><td>DingTalk アプリの Secret。App Key と同じ場所でコピーします。</td></tr></tbody></table><h2 id="動作確認" tabindex="-1">動作確認 <a class="header-anchor" href="#動作確認" aria-label="Permalink to &quot;動作確認&quot;">​</a></h2><p>プライベートチャットで Bot に <code>/help</code> を送るか、グループチャットで Bot を @メンションして <code>/help</code> を送ります。Bot がコマンド一覧を返せば、チャネルは接続できています。</p><h2 id="グループチャット" tabindex="-1">グループチャット <a class="header-anchor" href="#グループチャット" aria-label="Permalink to &quot;グループチャット&quot;">​</a></h2><p>Bot は DingTalk のグループチャットに対応しています。対応しているグループで Bot を @メンションすると返信します。</p><h2 id="無効化と認証情報の更新" tabindex="-1">無効化と認証情報の更新 <a class="header-anchor" href="#無効化と認証情報の更新" aria-label="Permalink to &quot;無効化と認証情報の更新&quot;">​</a></h2><p>Bot の <strong>プラットフォーム</strong> タブから、いつでもこのチャネルを無効化・削除できます。認証情報を更新するときは、同じパネルで <strong>App Key</strong> / <strong>App Secret</strong> を更新して保存してください。</p>',21)])])}const k=t(n,[["render",r]]);export{p as __pageData,k as default};
